`timescale 1ns/1ps
// FIR band-pass (noise filtering block). Coefficients come from fir_coeffs.vh (generated by Python).
//   y[n] = ( sum_k h[k] * x[n-k] ) >>> 12 , saturated to W bits.
//   SEQ = 0 : fully parallel (N_TAPS multipliers, one result per clock)          -> baseline
//   SEQ = 1 : ONE shared multiplier, one tap per clock (N_TAPS+2 clocks/sample)  -> optimised
module fir_bp #(parameter W = 16, parameter SEQ = 0, parameter ACCW = 48) (
    input  wire               clk,
    input  wire               rst,
    input  wire               in_valid,
    input  wire signed [W-1:0] x,
    output reg                out_valid,
    output reg  signed [W-1:0] y
);
    `include "fir_coeffs.vh"
    localparam integer HI =  (1 << (W-1)) - 1;
    localparam integer LO = -(1 << (W-1));
    integer k;
    generate
    if (SEQ == 0) begin : g_par
        reg signed [W-1:0]    sr [0:N_TAPS-2];
        reg signed [ACCW-1:0] acc;
        reg signed [ACCW-1:0] q;
        always @(posedge clk) begin
            if (rst) begin
                for (k = 0; k < N_TAPS-1; k = k + 1) sr[k] <= 0;
                y <= 0; out_valid <= 1'b0;
            end else begin
                out_valid <= in_valid;
                if (in_valid) begin
                    acc = fir_coef(0) * x;
                    for (k = 1; k < N_TAPS; k = k + 1) acc = acc + fir_coef(k) * sr[k-1];
                    q = acc >>> 12;
                    y <= (q > HI) ? HI : (q < LO) ? LO : q[W-1:0];
                    for (k = N_TAPS-2; k > 0; k = k - 1) sr[k] <= sr[k-1];
                    sr[0] <= x;
                end
            end
        end
    end else begin : g_seq
        reg signed [W-1:0]    shr [0:N_TAPS-1];      // shr[0] = newest sample
        reg signed [ACCW-1:0] acc_s;
        reg [7:0]             idx;
        reg                   busy, fin;
        wire signed [W-1:0]    smp  = shr[idx];
        wire signed [15:0]     coef = fir_coef(idx);
        wire signed [ACCW-1:0] prod = coef * smp;     // the ONE multiplier
        wire signed [ACCW-1:0] acc_n = acc_s + prod;
        wire signed [ACCW-1:0] qs    = acc_s >>> 12;
        always @(posedge clk) begin
            out_valid <= 1'b0;
            if (rst) begin
                for (k = 0; k < N_TAPS; k = k + 1) shr[k] <= 0;
                busy <= 0; fin <= 0; idx <= 0; acc_s <= 0; y <= 0;
            end else begin
                if (in_valid) begin
                    for (k = N_TAPS-1; k > 0; k = k - 1) shr[k] <= shr[k-1];
                    shr[0] <= x; idx <= 0; acc_s <= 0; busy <= 1'b1;
                end else if (busy) begin
                    acc_s <= acc_n;
                    if (idx == N_TAPS-1) begin busy <= 1'b0; fin <= 1'b1; end
                    else idx <= idx + 1;
                end
                if (fin) begin
                    y <= (qs > HI) ? HI : (qs < LO) ? LO : qs[W-1:0];
                    out_valid <= 1'b1; fin <= 1'b0;
                end
            end
        end
    end
    endgenerate
endmodule
